# Generated from pinned NuGet packages; see THIRD-PARTY-NOTICES.txt.
# Embedded dependencies keep the executable portable and offline.
function Initialize-SpectreAssemblies {
    if ('Spectre.Console.AnsiConsole' -as [type]) { return }
    $encoded=''
    $inputStream=New-Object IO.MemoryStream(,[Convert]::FromBase64String($encoded))
    $gzip=New-Object IO.Compression.GZipStream($inputStream,[IO.Compression.CompressionMode]::Decompress)
    $reader=New-Object IO.StreamReader($gzip,[Text.Encoding]::UTF8)
    try { $assemblies=ConvertFrom-Json $reader.ReadToEnd() } finally { $reader.Dispose(); $inputStream.Dispose() }
    foreach ($assembly in $assemblies) { [void][Reflection.Assembly]::Load([Convert]::FromBase64String($assembly.data)) }
}